  text?: string;
  /** `thinking` blocks (internal reasoning). */
  thinking?: string;
  /** `tool_use` blocks. */
  id?: string;
  name?: string;
  input?: Record<string, any>;
  /** `tool_result` blocks. */
  tool_use_id?: string;
  content?: string | Array<{ type: string; text?: string; [key: string]: any }>;
  is_error?: boolean;
  [key: string]: any;
}

