 * Transcript parsing utilities for Claude Code JSONL files.
 *
 * Claude Code writes chat records to a JSONL file, one {@link TranscriptEntry}
 * per line, in chronological order. These helpers read the file and locate the
 * "real" user prompts and assistant responses that anchor the MLflow trace.
 */

import { readFileSync } from 'node:fs';
import type { ContentBlock, TranscriptEntry } from './types.js';

export const NANOSECONDS_PER_MS = 1e6;

/**
 * Read and parse a Claude Code JSONL transcript file, returning one
 * {@link TranscriptEntry} per non-empty line, in order.
 */
export function readTranscript(filePath: string): TranscriptEntry[] {
  const content = readFileSync(filePath, 'utf-8');
  return content
    .split('\n')
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line) as TranscriptEntry);
}

/**
 * Convert a timestamp to nanoseconds since the Unix epoch.
 *
 * ISO date strings are parsed via `Date`. Numeric values are interpreted by
 * magnitude: `>= 1e13` are already nanoseconds, `>= 1e10` are milliseconds,
 * and anything smaller is treated as Unix seconds. Returns `null` for `null`,
 * `undefined`, empty string, or unparseable date strings.
 */
export function parseTimestampToNs(ts: string | number | null | undefined): number | null {
  if (ts === null || ts === undefined || ts === '') {
    return null;
  }

  if (typeof ts === 'number') {
    if (ts >= 1e13) {
      return Math.floor(ts);
    }
    if (ts >= 1e10) {
      return Math.floor(ts * 1e6);
    }
    return Math.floor(ts * 1e9);
  }

  const ms = new Date(ts).getTime();
  if (isNaN(ms)) {
    return null;
  }
  return Math.floor(ms * NANOSECONDS_PER_MS);
}

/**
 * Extract plain text from a message content value. A string is returned
 * unchanged; an array of content blocks yields the `text` fields of all
 * `text`-typed blocks joined with newlines (empty array → empty string).
 */
export function extractTextContent(
  content: string | Array<{ type: string; text?: string; [key: string]: any }>,
): string {
  if (typeof content === 'string') {
    return content;
  }
  return content
    .filter((block) => block.type === 'text')
    .map((block) => block.text ?? '')
    .join('\n');
}

/**
 * Return true if `entry` is a "real" user message — i.e. a human prompt rather
 * than a tool_result carrier, a compaction summary, or a skill-injection
 * message (which begins with `Base directory:`).
 */
export function isRealUserMessage(entry: TranscriptEntry): boolean {
  if (entry.type !== 'user') {
    return false;
  }
  if (entry.isCompactSummary === true) {
    return false;
  }

  const content = entry.message?.content;
  if (content == null) {
    return false;
  }

  if (Array.isArray(content) && content.some((block) => block.type === 'tool_result')) {
    return false;
  }

  const text = extractTextContent(content);
  if (text.startsWith('Base directory:')) {
    return false;
  }

  return true;
}

/**
 * Find the index of the last real user message (see {@link isRealUserMessage}).
 * Returns `null` for an empty transcript or when no real user message exists.
 */
export function findLastUserMessageIndex(entries: TranscriptEntry[]): number | null {
  if (entries.length === 0) {
    return null;
  }
  for (let i = entries.length - 1; i >= 0; i--) {
    if (isRealUserMessage(entries[i])) {
      return i;
    }
  }
  return null;
}

/**
 * Find the index of the first real user message (see {@link isRealUserMessage}).
 * Returns `null` when no real user message exists.
 */
export function findFirstUserMessageIndex(entries: TranscriptEntry[]): number | null {
  for (let i = 0; i < entries.length; i++) {
    if (isRealUserMessage(entries[i])) {
      return i;
    }
  }
  return null;
}

/**
 * Search from `startIndex` onward for the last assistant entry that contains
 * text content and return its extracted text, or `null` if none exists.
 */
export function findFinalAssistantResponse(
  entries: TranscriptEntry[],
  startIndex: number,
): string | null {
  let result: string | null = null;
  for (let i = Math.max(0, startIndex); i < entries.length; i++) {
    const entry = entries[i];
    if (entry.type !== 'assistant' || entry.message == null) {
      continue;
    }
    const text = extractTextContent(entry.message.content);
    if (text.trim()) {
      result = text;
    }
  }
  return result;
}

/** Return the content blocks of an entry's message, or `[]` for string/empty. */
export function getContentBlocks(entry: TranscriptEntry): ContentBlock[] {
  const content = entry.message?.content;
  return Array.isArray(content) ? content : [];
}

/** Return true if an entry carries any message content (text or blocks). */
export function hasMessageContent(entry: TranscriptEntry): boolean {
  const content = entry.message?.content;
  if (content == null) {
    return false;
  }
  return typeof content === 'string' ? content.length > 0 : content.length > 0;
}

/**
 * Normalize a tool_result content value into a single string for use as a
 * TOOL span output.
 */
export function toolResultToString(
  content: string | Array<{ type: string; text?: string; [key: string]: any }> | undefined,
): string {
  if (content == null) {
    return '';
  }
  if (typeof content === 'string') {
    return content;
  }
  return extractTextContent(content);
}
